test "test_sse_binary_codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const allocator = arena.allocator();

    var msg = SseBinary{
        .msg_seq_num = 123456789,
        .msg_body_len = 0,
        .msg_type = 33,
        .body = .{ .heartbeat = .{} },
        .checksum = 123456,
    };

    var buf = codec.Buffer.init(allocator, .big);
    defer buf.deinit();
    try msg.encode(&buf);

    var reader = codec.Reader.init(buf.written(), .big);
    const decoded = try SseBinary.decode(allocator, &reader);
    defer decoded.deinit(allocator);
    msg.msg_body_len = decoded.msg_body_len;
    msg.checksum = decoded.checksum;
    try std.testing.expect(msg.eql(decoded));
}
